import{_ as e,o,c as r,a2 as a}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/ko/export-ddl-preview.png",l="/relio/shots/ko/export-excel.png",x=JSON.parse('{"title":"DDL 만들기·내보내기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/export.md","filePath":"quick/export.md"}'),s={name:"quick/export.md"};function n(c,t,d,g,p,D){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="ddl-만들기·내보내기" tabindex="-1">DDL 만들기·내보내기 <a class="header-anchor" href="#ddl-만들기·내보내기" aria-label="Permalink to &quot;DDL 만들기·내보내기&quot;">​</a></h1><p>모델에서 DB에 실행할 SQL(DDL)과 Excel 정의서 같은 문서를 만듭니다.</p><h2 id="ddl" tabindex="-1">DDL <a class="header-anchor" href="#ddl" aria-label="Permalink to &quot;DDL&quot;">​</a></h2><ol><li>파일 › 내보내기 › DDL을 엽니다.</li><li>대상 DB와 버전을 고릅니다. 미리보기가 바로 바뀝니다. 지원 DB는 PostgreSQL·MySQL·MariaDB·Oracle·SQL Server·DB2·H2·HSQLDB·SQLite·Informix·MS Access·표준 SQL입니다.</li><li>만들 것(삭제 문장·테이블·인덱스·외래 키·시퀀스·주석 등)과 인코딩·줄바꿈을 고릅니다. 고른 설정은 문서에 저장되어 다음에도 쓰입니다.</li><li>파일로 저장합니다. 창 오른쪽 아래 알림의 <strong>폴더 열기</strong>로 만든 파일을 바로 엽니다.</li></ol><figure class="shot" data-scene="export-ddl-preview"><img src="'+i+'" alt="DDL 내보내기 창 — 대상 DB와 버전을 고르고 미리보기를 보는 모습" loading="lazy"><figcaption>DDL 내보내기 창 — 대상 DB와 버전을 고르고 미리보기를 보는 모습</figcaption></figure><p>그 DB 버전에서 쓸 수 없는 문법은 빼거나 바꾸고 경고로 알립니다. DDL을 실행하면 실패할 오류가 있으면 창에 &quot;오류가 n개 있습니다&quot;가 보입니다.</p><h2 id="그-밖의-내보내기" tabindex="-1">그 밖의 내보내기 <a class="header-anchor" href="#그-밖의-내보내기" aria-label="Permalink to &quot;그 밖의 내보내기&quot;">​</a></h2><p>파일 › 내보내기에서 종류를 고릅니다.</p><ul><li><strong>Excel</strong> — 테이블 정의서(한국어 기본 양식 포함). ERMaster <code>.xls</code> 템플릿도 쓸 수 있고 출력은 <code>.xlsx</code>입니다.</li><li><strong>이미지</strong> — PNG·JPG·BMP·SVG.</li><li><strong>HTML</strong>·<strong>Markdown</strong> — 인터넷 없이 보는 문서.</li><li><strong>DBML</strong>·<strong>Mermaid</strong>·<strong>모델 JSON</strong> — 다른 도구에 붙여 넣기. 클립보드로 바로 복사할 수도 있습니다.</li><li><strong>Java</strong>·<strong>테스트 데이터</strong> — 클래스 소스·JPA Entity, INSERT SQL·DBUnit XML.</li></ul><figure class="shot" data-scene="export-excel"><img src="'+l+'" alt="Excel 내보내기 창 — 양식과 저장 위치 고르기" loading="lazy"><figcaption>Excel 내보내기 창 — 양식과 저장 위치 고르기</figcaption></figure><p><strong>자세히</strong> → <a href="/relio/features/ddl">DDL</a> · <a href="/relio/features/export">내보내기</a></p>',11)])])}const f=e(s,[["render",n]]);export{x as __pageData,f as default};
